pub(crate) fn source_color(value:&str)->Option<[f64;4]>{
    let value=value.trim();if matches!(value,"transparent"|"none"){return Some([0.0;4]);}
    if let Some(hex)=value.strip_prefix('#'){return match hex.len(){3=>{let b=hex.as_bytes();Some([u8::from_str_radix(&(b[0]as char).to_string(),16).ok()?as f64*17.0,u8::from_str_radix(&(b[1]as char).to_string(),16).ok()?as f64*17.0,u8::from_str_radix(&(b[2]as char).to_string(),16).ok()?as f64*17.0,1.0])},6|8=>Some([u8::from_str_radix(&hex[0..2],16).ok()?as f64,u8::from_str_radix(&hex[2..4],16).ok()?as f64,u8::from_str_radix(&hex[4..6],16).ok()?as f64,if hex.len()==8{u8::from_str_radix(&hex[6..8],16).ok()?as f64/255.0}else{1.0}]),_=>None};}
    let contents=value.strip_prefix("rgba(").or_else(||value.strip_prefix("rgb("))?.strip_suffix(')')?;let mut values=contents.split(',').map(|v|v.trim().parse::<f64>());Some([values.next()?.ok()?,values.next()?.ok()?,values.next()?.ok()?,values.next().map(|v|v.ok()).unwrap_or(Some(1.0))?])
}
fn source_mix_color(a:&str,b:&str,k:f64)->String{let(Some(mut a),Some(mut b))=(source_color(a),source_color(b))else{return if k<0.5{a}else{b}.to_owned();};if a[3]==0.0{a[..3].copy_from_slice(&b[..3]);}if b[3]==0.0{b[..3].copy_from_slice(&a[..3]);}let v=[0,1,2,3].map(|i|a[i]+(b[i]-a[i])*k);format!("rgba({}, {}, {}, {})",v[0].round(),v[1].round(),v[2].round(),(v[3]*1000.0).round()/1000.0)}
fn source_scale_px(css:&str,scale:f64)->String{let mut out=String::with_capacity(css.len());let mut i=0;let bytes=css.as_bytes();while i<bytes.len(){if bytes[i].is_ascii_digit()||matches!(bytes[i],b'.'|b'-'){let start=i;i+=1;while i<bytes.len()&&(bytes[i].is_ascii_digit()||bytes[i]==b'.'){i+=1;}if css[i..].starts_with("px"){if let Ok(n)=css[start..i].parse::<f64>(){out.push_str(&(n*scale).to_string());out.push_str("px");i+=2;continue;}}out.push_str(&css[start..i]);}else{let ch=css[i..].chars().next().unwrap();out.push(ch);i+=ch.len_utf8();}}out}
impl<'a> Scene<'a>{
    fn selection_at(&self,local_ms:f64)->Option<(usize,f64)>{if self.selection_count==0{return None;}let index=self.selection_steps.partition_point(|&t|t<=local_ms/1000.0).checked_sub(1)?;Some((index%self.selection_count,local_ms/1000.0-self.selection_steps[index]))}
    fn selected_border(&mut self,item:&Value,border:&str){let Some(mode)=item["mode"].as_u64()else{return};if self.selection_count==0{return;}let mut parts=border.splitn(3,' ');let width=parts.next().unwrap_or("0").trim_end_matches("px").parse::<f64>().unwrap_or(0.0)*self.scale;let _style=parts.next();let color=parts.next().unwrap_or("transparent");for(i,&t)in self.selection_steps.iter().enumerate(){let before=i>0&&(i-1)%self.selection_count==mode as usize;let after=i%self.selection_count==mode as usize;if before!=after{let(a,b)=if after{(color,self.theme.accent)}else{(self.theme.accent,color)};self.body.push_str(&format!("<Animate prop=\"stroke\" from={} to={} start=\"{}ms\" duration=\"0.000001ms\" ease=\"linear\"/><Animate prop=\"strokeWidth\" from={{{}}} to={{{}}} start=\"{}ms\" duration=\"0.000001ms\" ease=\"linear\"/>",q(a),q(b),t*1000.0,if before{2.5*self.scale}else{width},if after{2.5*self.scale}else{width},t*1000.0));}}}
    pub fn music_beat(&self,local_ms:f64)->Option<crate::music::Beat>{self.music.as_ref().map(|m|m.beat_at(self.start+local_ms/1000.0))}
    pub fn music_amp(&self,local_ms:f64,part:&str)->f64{let beat=&SOURCE_THEMES[self.theme.name]["beat"];self.music.as_ref().map(|m|m.amp(self.start+local_ms/1000.0,beat[part].as_f64().unwrap_or(0.0),beat["decay"].as_f64().unwrap(),beat["weak"].as_f64().unwrap())).unwrap_or(0.0)}
    fn depth_shadow(&self,d:&Value,tone:&str,shadow:&str)->String{let th=&SOURCE_THEMES[self.theme.name];let depth=&th["depth"];let px=depth["px"].as_f64().unwrap_or(0.0);if depth["kind"]=="none"||px==0.0{return shadow.to_owned();}let toneink=if tone=="warning"{self.theme.warning}else if tone=="accent"{self.theme.accent}else{self.theme.line};let mut edge=if depth["kind"]=="outline"{format!("0 {px}px 0 -1px {}, 0 {px}px 0 0.5px {toneink}",self.theme.bg)}else{let focus=d["role"]=="focus";let face=if focus{self.theme.focus}else if tone=="warning"{th["exceptionTint"].as_str().unwrap()}else if tone=="accent"{th["accentTint"].as_str().unwrap()}else{self.theme.surface};let ink=if focus{"#000000"}else if tone=="warning"{self.theme.warning}else if tone=="accent"{self.theme.accent}else{self.theme.ink};format!("0 {px}px 0 0 {}",source_mix_color(face,ink,depth["mix"].as_f64().unwrap()))};if let Some(rim)=depth["rim"].as_str().filter(|s|!s.is_empty()){edge=format!("{rim}, {edge}");}if !shadow.is_empty()&&shadow!="none"{edge.push_str(", ");edge.push_str(shadow);}edge}
}
#[cfg(test)]mod source_style_tests{use super::*;#[test]fn source_css_lengths_and_transparent_hues(){assert_eq!(source_scale_px("0 4px 0 -1px rgba(20, 30, 40, .5)",1.5),"0 6px 0 -1.5px rgba(20, 30, 40, .5)");assert_eq!(source_mix_color("transparent","#ff0000",0.5),"rgba(255, 0, 0, 0.5)");}}
